{"content":"//! Netmaker adapter — bridges Netmaker HTTP REST API to gRPC.
//! Connects via unix socket: /run/netmaker/api.sock

use crate::proto::{
    netmaker_service_server::NetmakerService, ExecuteCommandRequest, ExecuteCommandResponse,
    GetNetworkRequest, GetNetworkResponse, GetNodeRequest, GetNodeResponse, HealthRequest,
    HealthResponse, Host, JoinNetworkRequest, JoinNetworkResponse, LeaveNetworkRequest,
    LeaveNetworkResponse, ListHostsRequest, ListHostsResponse, ListNetworksRequest,
    ListNetworksResponse, ListNodesRequest, ListNodesResponse, NetmakerEvent, Network, Node,
    RestartServiceRequest, RestartServiceResponse, StreamEventsRequest,
};
use async_trait::async_trait;
use serde_json::Value as JsonValue;
use std::pin::Pin;
use tokio::process::Command;
use tokio_stream::Stream;
use tonic::{Request, Response, Status};

#[allow(dead_code)]
const API_SOCK: &str = "/run/netmaker/api.sock";

pub struct NetmakerAdapter {
    client: reqwest::Client,
    #[allow(dead_code)]
    base_url: String,
}

impl NetmakerAdapter {
    pub fn new() -> Self {
        // Route HTTP through the service endpoint exposed by the socket-backed
        // registration path.
        let client = reqwest::Client::builder().build().expect("reqwest client");
        Self {
            client,
            base_url: "http://localhost".to_string(),
        }
    }

    async fn get<T: serde::de::DeserializeOwned>(&self, path: &str) -> Result<T, Status> {
        let master_key =
            std::env::var("NETMAKER_MASTER_KEY").unwrap_or_else(|_| "masterkey".to_string());

        // The socket-backed registration path resolves the service endpoint;
        // the adapter keeps a conventional HTTP client here.
        let url = format!("http://127.0.0.1:8081{}", path);
        let resp = self
            .client
            .get(&url)
            .header("Authorization", format!("Bearer {}", master_key))
            .send()
            .await
            .map_err(|e| Status::unavailable(format!("Netmaker API unavailable: {}", e)))?;

        if !resp.status().is_success() {
            return Err(Status::internal(format!(
                "Netmaker API error: {}",
                resp.status()
            )));
        }

        resp.json::<T>()
            .await
            .map_err(|e| Status::internal(format!("Netmaker API parse error: {}", e)))
    }

    async fn patch_netclient_config<F>(&self, edit: F) -> Result<(), Status>
    where
        F: FnOnce(&mut JsonValue),
    {
        let path = "/etc/netclient/netclient.json";
        let mut config = match tokio::fs::read_to_string(path).await {
            Ok(content) => serde_json::from_str::<JsonValue>(&content)
                .map_err(|e| Status::internal(format!("netclient config parse error: {}", e)))?,
            Err(_) => serde_json::json!({}),
        };

        edit(&mut config);

        tokio::fs::create_dir_all("/etc/netclient")
            .await
            .map_err(|e| Status::internal(format!("netclient config dir error: {}", e)))?;
        tokio::fs::write(
            path,
            serde_json::to_string_pretty(&config).unwrap_or_else(|_| "{}".to_string()),
        )
        .await
        .map_err(|e| Status::internal(format!("netclient config write error: {}", e)))?;
        Ok(())
    }

    async fn restart_netclient(&self) -> Result<(), Status> {
        let resp = self
            .execute_command(Request::new(ExecuteCommandRequest {
                command: Some(crate::proto::execute_command_request::Command::Restart(
                    RestartServiceRequest {
                        service: "netclient".to_string(),
                    },
                )),
            }))
            .await?
            .into_inner();
        if resp.success {
            Ok(())
        } else {
            Err(Status::internal(resp.stderr))
        }
    }
}

impl Default for NetmakerAdapter {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl NetmakerService for NetmakerAdapter {
    async fn get_server_health(
        &self,
        _req: Request<HealthRequest>,
    ) -> Result<Response<HealthResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct HealthResp {
            status: String,
            version: Option<String>,
        }
        let r: HealthResp = self.get("/api/server/health").await?;
        Ok(Response::new(HealthResponse {
            status: r.status,
            version: r.version.unwrap_or_default(),
        }))
    }

    async fn get_network(
        &self,
        req: Request<GetNetworkRequest>,
    ) -> Result<Response<GetNetworkResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct Net {
            netid: String,
            addressrange: Option<String>,
            addressrange6: Option<String>,
            localrange: Option<String>,
        }
        let n: Net = self
            .get(&format!("/api/networks/{}", req.into_inner().name))
            .await?;
        Ok(Response::new(GetNetworkResponse {
            network: Some(Network {
                name: n.netid,
                address_range: n.addressrange.unwrap_or_default(),
                address_range6: n.addressrange6.unwrap_or_default(),
                is_local: n.localrange.is_some(),
            }),
        }))
    }

    async fn list_hosts(
        &self,
        _req: Request<ListHostsRequest>,
    ) -> Result<Response<ListHostsResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct H {
            id: String,
            name: Option<String>,
            publickey: Option<String>,
            version: Option<String>,
        }
        let raw: Vec<H> = self.get("/api/hosts").await?;
        let hosts = raw
            .into_iter()
            .map(|h| Host {
                id: h.id,
                name: h.name.unwrap_or_default(),
                public_key: h.publickey.unwrap_or_default(),
                version: h.version.unwrap_or_default(),
            })
            .collect();
        Ok(Response::new(ListHostsResponse { hosts }))
    }

    async fn restart_service(
        &self,
        req: Request<RestartServiceRequest>,
    ) -> Result<Response<RestartServiceResponse>, Status> {
        let service = req.into_inner().service;
        if service == "netclient" {
            self.restart_netclient().await?;
        } else {
            return Err(Status::invalid_argument(format!(
                "unsupported service '{}'",
                service
            )));
        }
        Ok(Response::new(RestartServiceResponse {
            success: true,
            message: format!("{} restarted", service),
        }))
    }

    async fn execute_command(
        &self,
        req: Request<ExecuteCommandRequest>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        let command = req.into_inner().command.ok_or_else(|| {
            Status::invalid_argument("missing command variant for netclient execution")
        })?;

        match command {
            crate::proto::execute_command_request::Command::Join(join) => {
                self.patch_netclient_config(|config| {
                    config["enabled"] = serde_json::json!(true);
                    config["default_network"] = serde_json::json!(join.network);
                    config["enrollment_token"] = serde_json::json!(join.token);
                    config["interface"] = serde_json::json!("netmaker");
                    config["inittype"] = serde_json::json!(6);
                })
                .await?;
                self.restart_netclient().await?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: true,
                    exit_code: 0,
                    stdout: "joined network".to_string(),
                    stderr: String::new(),
                }))
            }
            crate::proto::execute_command_request::Command::Leave(leave) => {
                self.patch_netclient_config(|config| {
                    if config.get("default_network").and_then(|v| v.as_str())
                        == Some(leave.network.as_str())
                    {
                        config["default_network"] = serde_json::json!("");
                    }
                    config["enabled"] = serde_json::json!(false);
                    config["enrollment_token"] = serde_json::json!(null);
                })
                .await?;
                self.restart_netclient().await?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: true,
                    exit_code: 0,
                    stdout: "left network".to_string(),
                    stderr: String::new(),
                }))
            }
            crate::proto::execute_command_request::Command::Restart(restart) => {
                if restart.service != "netclient" {
                    return Err(Status::invalid_argument(format!(
                        "unsupported service '{}'",
                        restart.service
                    )));
                }
                let output = Command::new(op_core::runit::SV_BIN)
                    .args(["restart", "netclient"])
                    .output()
                    .await
                    .map_err(|e| Status::internal(format!("failed to execute sv: {}", e)))?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: output.status.success(),
                    exit_code: output.status.code().unwrap_or(-1),
                    stdout: String::from_utf8_lossy(&output.stdout).to_string(),
                    stderr: String::from_utf8_lossy(&output.stderr).to_string(),
                }))
            }
            crate::proto::execute_command_request::Command::Connect(req) => {
                self.run_command("connect", vec![req.network]).await
            }
            crate::proto::execute_command_request::Command::Disconnect(req) => {
                self.run_command("disconnect", vec![req.network]).await
            }
            crate::proto::execute_command_request::Command::List(_) => {
                self.run_command("list", vec![]).await
            }
            crate::proto::execute_command_request::Command::Peers(_) => {
                self.run_command("peers", vec![]).await
            }
            crate::proto::execute_command_request::Command::Ping(req) => {
                self.run_command("ping", vec![req.peer]).await
            }
            crate::proto::execute_command_request::Command::Pull(_) => {
                self.run_command("pull", vec![]).await
            }
            crate::proto::execute_command_request::Command::Push(_) => {
                self.run_command("push", vec![]).await
            }
            crate::proto::execute_command_request::Command::Register(req) => {
                self.run_command("register", vec![req.instance]).await
            }
            crate::proto::execute_command_request::Command::Server(req) => {
                let mut args = vec![req.subcommand];
                args.extend(req.args);
                self.run_command("server", args).await
            }
            crate::proto::execute_command_request::Command::Install(_) => {
                self.run_command("install", vec![]).await
            }
            crate::proto::execute_command_request::Command::Uninstall(_) => {
                self.run_command("uninstall", vec![]).await
            }
            crate::proto::execute_command_request::Command::Use(req) => {
                self.run_command("use", vec![req.version]).await
            }
            crate::proto::execute_command_request::Command::Version(_) => {
                self.run_command("version", vec![]).await
            }
        }
    }

    type StreamEventsStream = Pin<Box<dyn Stream<Item = Result<NetmakerEvent, Status>> + Send>>;

    async fn stream_events(
        &self,
        _req: Request<StreamEventsRequest>,
    ) -> Result<Response<Self::StreamEventsStream>, Status> {
        // Poll Netmaker's metric endpoint as a simple event stream
        let stream = async_stream::stream! {
            loop {
                tokio::time::sleep(tokio::time::Duration::from_secs(30)).await;
                yield Ok(NetmakerEvent {
                    event_type: "heartbeat".to_string(),
                    payload_json: "{}".to_string(),
                });
            }
        };
        Ok(Response::new(Box::pin(stream)))
    }
}

impl NetmakerAdapter {
    async fn run_command(
        &self,
        name: &str,
        args: Vec<String>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        let mut cmd = Command::new("netclient");
        cmd.arg(name);
        for arg in args {
            cmd.arg(arg);
        }
        let output = cmd
            .output()
            .await
            .map_err(|e| Status::internal(format!("failed to execute netclient: {}", e)))?;
        Ok(Response::new(ExecuteCommandResponse {
            success: output.status.success(),
            exit_code: output.status.code().unwrap_or(-1),
            stdout: String::from_utf8_lossy(&output.stdout).to_string(),
            stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        }))
    }
}
"}

{"content":"//! Native, bounded building blocks for the inactive netmk Phase 1 runit graph.
//!
//! This binary never activates services. It owns only the declared netmk
//! attachment, feature policy rules/route, feature-cookie flows, and
//! authenticated adapter checks.

use anyhow::{bail, Context, Result};
use op_grpc_bridge::grpc_client::DEFAULT_NETMAKER_ADAPTER_ADDR;
use op_grpc_bridge::{GrpcClientPool, RemoteOperationClient};
use op_plugins::state_plugins::incus::IncusPlugin;
use op_plugins::state_plugins::oci::{
    GrpcAdapterConfig, OciContainerConfig, OciPlugin, PortAttachConfig,
};
use op_plugins::state_plugins::openflow::{FlowAction, FlowEntry, OpenFlowPlugin};
use std::collections::{HashMap, HashSet};
use std::process::Command;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

const COOKIE_PREFIX: u64 = 0x4e4d4b0000000000;
const COOKIE_MASK: u64 = 0xffffff0000000000;
const BRIDGE: &str = "ovsbr0";
const PORT: &str = "netmk";
const HOST_INSIDE: &str = "svc0";
const XRAY_EXISTING_ADDRESS: &str = "10.200.0.1";
const XRAY_NETMK_ADDRESS: &str = "10.200.1.2";
const FEATURE_SOURCE: &str = "10.200.1.1";

fn env_or(name: &str, default: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| default.to_string())
}

fn is_already_exists(error: &anyhow::Error) -> bool {
    let text = format!("{error:#}").to_ascii_lowercase();
    text.contains("file exists") || text.contains("eexist") || text.contains("os error 17")
}

fn netmaker_attachment() -> OciContainerConfig {
    OciContainerConfig {
        name: env_or("NETMAKER_INSTANCE", "netmaker"),
        loopback_required: true,
        port_attach: Some(PortAttachConfig {
            bridge: BRIDGE.to_string(),
            port_name: PORT.to_string(),
            ip_addrs: vec![format!("{FEATURE_SOURCE}/30")],
            gateway: XRAY_NETMK_ADDRESS.to_string(),
            routes: Vec::new(),
        }),
        grpc_adapter: Some(GrpcAdapterConfig {
            binary: "op-grpc-adapters".to_string(),
            socket: "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock".to_string(),
            host_endpoint: DEFAULT_NETMAKER_ADAPTER_ADDR.to_string(),
        }),
        supervision: Some("runit".to_string()),
        ..OciContainerConfig::default()
    }
}

async fn attachment(command: &str) -> Result<()> {
    let plugin = OciPlugin::new();
    let desired = netmaker_attachment();
    match command {
        "reconcile" => {
            for change in plugin.reconcile_container_attachment(&desired).await? {
                println!("{change}");
            }
            if !plugin.verify_container_attachment(&desired).await? {
                bail!("netmaker attachment did not pass independent verification");
            }
        }
        "verify" => {
            if !plugin.verify_container_attachment(&desired).await? {
                bail!("netmaker attachment is not ready");
            }
        }
        "teardown" => plugin.delete_container_attachment(&desired).await?,
        other => bail!("unknown attachment action '{other}'"),
    }
    Ok(())
}

async fn discover_xray_inside(pid: u32) -> Result<String> {
    let interfaces = op_network::rtnetlink::in_network_namespace(pid, || async {
        op_network::rtnetlink::list_interfaces().await
    })
    .await?;
    interfaces
        .into_iter()
        .find(|interface| {
            interface.name != "lo"
                && interface.addresses.iter().any(|address| {
                    address.family == "inet" && address.address == XRAY_EXISTING_ADDRESS
                })
        })
        .map(|interface| interface.name)
        .with_context(|| {
            format!(
                "no xray inside interface carries required existing address {XRAY_EXISTING_ADDRESS}"
            )
        })
}

async fn host_return_route_ready() -> Result<bool> {
    let routes = op_network::rtnetlink::list_routes_for_interface(HOST_INSIDE).await?;
    Ok(routes.iter().any(|route| {
        route.get("destination").and_then(|value| value.as_str()) == Some("10.200.1.0/30")
            && route.get("gateway").and_then(|value| value.as_str()) == Some(XRAY_EXISTING_ADDRESS)
            && route.get("table").and_then(|value| value.as_u64()) == Some(254)
    }))
}

async fn egress_network_ready() -> Result<bool> {
    let xray_name = env_or("XRAY_INSTANCE", "xray");
    let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
    let inside = discover_xray_inside(pid).await?;
    let interfaces = op_network::rtnetlink::in_network_namespace(pid, move || async move {
        op_network::rtnetlink::list_interfaces().await
    })
    .await?;
    let address_ready = interfaces.iter().any(|interface| {
        interface.name == inside
            && interface.addresses.iter().any(|address| {
                address.family == "inet"
                    && address.address == XRAY_NETMK_ADDRESS
                    && address.prefix_len == 30
            })
    });
    Ok(address_ready
        && host_return_route_ready().await?
        && op_network::rtnetlink::verify_netmk_policy_rules().await?)
}

async fn egress_network(command: &str) -> Result<()> {
    match command {
        "reconcile" => {
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let initial_pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(initial_pid).await?;
            if let Err(error) = op_network::rtnetlink::add_ipv4_address_in_netns(
                initial_pid,
                &inside,
                XRAY_NETMK_ADDRESS,
                30,
            )
            .await
            {
                if !is_already_exists(&error) {
                    return Err(error).context("add xray netmk gateway address");
                }
            }
            let current_pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            if current_pid != initial_pid {
                bail!(
                    "xray restarted during reconciliation (PID {initial_pid} -> {current_pid}); retry"
                );
            }
            if !host_return_route_ready().await? {
                if let Err(error) = op_network::rtnetlink::add_ipv4_route(
                    "10.200.1.0/30",
                    Some(XRAY_EXISTING_ADDRESS),
                    HOST_INSIDE,
                    Some(254),
                )
                .await
                {
                    if !is_already_exists(&error) {
                        return Err(error).context("add feature host return route");
                    }
                }
            }
            op_network::rtnetlink::reconcile_netmk_policy_rules().await?;
            if !egress_network_ready().await? {
                bail!("native xray/host route and policy-rule verification failed");
            }
            println!("xray_inside={inside}");
            println!("xray_pid={current_pid}");
        }
        "inspect" => {
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(pid).await?;
            println!("xray_inside={inside}");
            println!("xray_pid={pid}");
        }
        "verify" => {
            if !egress_network_ready().await? {
                bail!("native xray/host egress integration is not ready");
            }
        }
        "teardown" => {
            op_network::rtnetlink::delete_netmk_policy_rules().await?;
            op_network::rtnetlink::delete_ipv4_route(
                "10.200.1.0/30",
                Some(XRAY_EXISTING_ADDRESS),
                HOST_INSIDE,
                Some(254),
            )
            .await?;
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(pid).await?;
            op_network::rtnetlink::del_ipv4_address_in_netns(pid, &inside, XRAY_NETMK_ADDRESS, 30)
                .await?;
        }
        other => bail!("unknown egress-network action '{other}'"),
    }
    Ok(())
}

fn parse_ports(values: &[String]) -> Result<Vec<u16>> {
    if values.is_empty() {
        bail!("at least one approved UDP destination port is required");
    }
    let mut seen = HashSet::new();
    let mut ports = Vec::new();
    for value in values {
        let port: u16 = value
            .parse()
            .with_context(|| format!("invalid UDP destination port '{value}'"))?;
        if port == 0 {
            bail!("UDP destination port must be between 1 and 65535");
        }
        if seen.insert(port) {
            ports.push(port);
        }
    }
    ports.sort_unstable();
    Ok(ports)
}

fn desired_flows(ports: &[u16]) -> Vec<FlowEntry> {
    let mut flows = vec![FlowEntry {
        table: 0,
        priority: 100,
        match_fields: HashMap::from([
            ("in_port".to_string(), PORT.to_string()),
            ("arp".to_string(), String::new()),
        ]),
        actions: vec![FlowAction::Normal],
        cookie: Some(COOKIE_PREFIX | 0x01),
        idle_timeout: 0,
        hard_timeout: 0,
    }];
    for port in ports {
        flows.push(FlowEntry {
            table: 0,
            priority: 100,
            match_fields: HashMap::from([
                ("in_port".to_string(), PORT.to_string()),
                ("udp".to_string(), String::new()),
                ("tp_dst".to_string(), port.to_string()),
            ]),
            actions: vec![FlowAction::Normal],
            cookie: Some(COOKIE_PREFIX | 0x10000 | u64::from(*port)),
            idle_timeout: 0,
            hard_timeout: 0,
        });
    }
    flows.push(FlowEntry {
        table: 0,
        priority: 50,
        match_fields: HashMap::from([("in_port".to_string(), PORT.to_string())]),
        actions: vec![FlowAction::Drop],
        cookie: Some(COOKIE_PREFIX | 0xff),
        idle_timeout: 0,
        hard_timeout: 0,
    });
    flows
}

async fn openflow(command: &str, port_args: &[String]) -> Result<()> {
    let plugin = OpenFlowPlugin::new();
    match command {
        "reconcile" | "verify" => {
            let ports = parse_ports(port_args)?;
            let desired = desired_flows(&ports);
            if command == "reconcile" {
                for change in plugin
                    .reconcile_cookie_scoped(BRIDGE, &desired, COOKIE_PREFIX, COOKIE_MASK)
                    .await?
                {
                    println!("{change}");
                }
            }
            if !plugin
                .verify_cookie_scoped(BRIDGE, &desired, COOKIE_PREFIX, COOKIE_MASK)
                .await?
            {
                bail!("authoritative feature-cookie OpenFlow verification failed");
            }
        }
        "teardown" => {
            let deleted = plugin
                .clear_cookie_scoped(BRIDGE, COOKIE_PREFIX, COOKIE_MASK)
                .await?;
            println!("deleted_flows={deleted}");
        }
        other => bail!("unknown openflow action '{other}'"),
    }
    Ok(())
}

fn adapter_client() -> RemoteOperationClient {
    let endpoint = env_or("NETMAKER_ADAPTER_ADDR", DEFAULT_NETMAKER_ADAPTER_ADDR);
    RemoteOperationClient::new_with_netmaker_address(
        Arc::new(GrpcClientPool::new()),
        "http://127.0.0.1:8090",
        &endpoint,
        "op-netmk-reconcile",
    )
}

async fn adapter_health() -> Result<()> {
    let health = adapter_client().netmaker_health().await?;
    let status = health.status.to_ascii_lowercase();
    if !matches!(status.as_str(), "ok" | "healthy" | "running" | "success") {
        bail!(
            "Netmaker adapter returned unhealthy status {:?}",
            health.status
        );
    }
    println!("status={}", health.status);
    println!("version={}", health.version);
    Ok(())
}

fn endpoint_port(value: &str) -> Result<Option<u16>> {
    if value == "(none)" {
        return Ok(None);
    }
    let port_text = value
        .rsplit_once(':')
        .map(|(_, port)| port)
        .with_context(|| format!("WireGuard endpoint has no port: {value}"))?;
    let port: u16 = port_text
        .parse()
        .with_context(|| format!("invalid WireGuard endpoint port '{port_text}'"))?;
    if port == 0 {
        bail!("WireGuard endpoint port must be non-zero");
    }
    Ok(Some(port))
}

async fn discover_netclient_ports() -> Result<Vec<u16>> {
    let name = env_or("NETMAKER_INSTANCE", "netmaker");
    let pid = IncusPlugin::resolve_instance_pid(&name).await?;
    op_network::rtnetlink::in_network_namespace(pid, move || async move {
        let mut ports = HashSet::new();
        for query in [["show", "all", "listen-port"], ["show", "all", "endpoints"]] {
            let output = Command::new("/usr/bin/wg")
                .args(query)
                .output()
                .with_context(|| format!("execute /usr/bin/wg {}", query.join(" ")))?;
            if !output.status.success() {
                bail!(
                    "wg {} failed: {}",
                    query.join(" "),
                    String::from_utf8_lossy(&output.stderr).trim()
                );
            }
            for line in String::from_utf8_lossy(&output.stdout).lines() {
                let Some(value) = line.split_whitespace().last() else {
                    continue;
                };
                let port = if query[2] == "listen-port" {
                    let port: u16 = value
                        .parse()
                        .with_context(|| format!("invalid WireGuard listen port '{value}'"))?;
                    if port == 0 {
                        continue;
                    }
                    port
                } else {
                    let Some(port) = endpoint_port(value)? else {
                        continue;
                    };
                    port
                };
                ports.insert(port);
            }
        }
        let mut ports: Vec<_> = ports.into_iter().collect();
        ports.sort_unstable();
        if ports.is_empty() {
            bail!("no Netclient WireGuard listen or peer endpoint ports discovered");
        }
        Ok(ports)
    })
    .await
}

async fn recent_netclient_handshake(max_age_seconds: u64) -> Result<bool> {
    let name = env_or("NETMAKER_INSTANCE", "netmaker");
    let pid = IncusPlugin::resolve_instance_pid(&name).await?;
    op_network::rtnetlink::in_network_namespace(pid, move || async move {
        let output = Command::new("/usr/bin/wg")
            .args(["show", "all", "latest-handshakes"])
            .output()
            .context("execute /usr/bin/wg in netmaker network namespace")?;
        if !output.status.success() {
            bail!(
                "wg show failed: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .context("system clock before UNIX epoch")?
            .as_secs();
        for line in String::from_utf8_lossy(&output.stdout).lines() {
            let timestamp = line
                .split_whitespace()
                .last()
                .and_then(|value| value.parse::<u64>().ok())
                .unwrap_or(0);
            if timestamp > 0 && now.saturating_sub(timestamp) <= max_age_seconds {
                return Ok(true);
            }
        }
        Ok(false)
    })
    .await
}

async fn netclient(command: &str, max_age: Option<&String>) -> Result<()> {
    match command {
        "restart" => {
            if !adapter_client().netmaker_restart("netclient").await? {
                bail!("adapter reported netclient restart failure");
            }
        }
        "health" => {
            adapter_health().await?;
            let list = adapter_client().netclient_list().await?;
            if !list.success {
                bail!("netclient list failed: {}", list.stderr.trim());
            }
            let max_age = max_age
                .map(|value| value.parse::<u64>())
                .transpose()
                .context("invalid maximum handshake age")?
                .unwrap_or(180);
            if !recent_netclient_handshake(max_age).await? {
                bail!("no netclient WireGuard handshake within {max_age} seconds");
            }
        }
        other => bail!("unknown netclient action '{other}'"),
    }
    Ok(())
}

fn usage() -> ! {
    eprintln!(
        "usage: op-netmk-reconcile \
         attachment <reconcile|verify|teardown> | \
         egress-network <reconcile|inspect|verify|teardown> | \
         openflow <reconcile|verify|teardown> [UDP_PORT ...] | \
         adapter-health | peer-ports | netclient <restart|health> [MAX_HANDSHAKE_AGE] | \
         instance-pid <NAME>"
    );
    std::process::exit(2)
}

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.as_slice() {
        [group, action] if group == "attachment" => attachment(action).await,
        [group, action] if group == "egress-network" => egress_network(action).await,
        [group, action, ports @ ..] if group == "openflow" => openflow(action, ports).await,
        [command] if command == "adapter-health" => adapter_health().await,
        [command] if command == "peer-ports" => {
            for port in discover_netclient_ports().await? {
                println!("{port}");
            }
            Ok(())
        }
        [group, action] if group == "netclient" => netclient(action, None).await,
        [group, action, max_age] if group == "netclient" => netclient(action, Some(max_age)).await,
        [command, name] if command == "instance-pid" => {
            println!("{}", IncusPlugin::resolve_instance_pid(name).await?);
            Ok(())
        }
        _ => usage(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn desired_flows_use_only_destination_ports_and_feature_cookies() {
        let flows = desired_flows(&[51820, 51821]);
        assert_eq!(flows.len(), 4);
        assert!(flows.iter().all(|flow| {
            flow.cookie
                .is_some_and(|cookie| cookie & COOKIE_MASK == COOKIE_PREFIX)
        }));
        assert!(flows
            .iter()
            .flat_map(|flow| flow.match_fields.keys())
            .all(|key| key != "tp_src"));
        assert!(flows
            .iter()
            .any(|flow| { flow.priority == 50 && flow.actions == vec![FlowAction::Drop] }));
    }

    #[test]
    fn parses_wireguard_endpoint_ports() {
        assert_eq!(endpoint_port("203.0.113.4:51820").unwrap(), Some(51820));
        assert_eq!(endpoint_port("[2001:db8::4]:51821").unwrap(), Some(51821));
        assert_eq!(endpoint_port("(none)").unwrap(), None);
        assert!(endpoint_port("203.0.113.4").is_err());
        assert!(endpoint_port("203.0.113.4:0").is_err());
    }

    #[test]
    fn peer_ports_are_required_valid_and_deduplicated() {
        assert!(parse_ports(&[]).is_err());
        assert!(parse_ports(&["0".to_string()]).is_err());
        assert_eq!(
            parse_ports(&[
                "51821".to_string(),
                "51820".to_string(),
                "51821".to_string()
            ])
            .unwrap(),
            vec![51820, 51821]
        );
    }
}
